import { toast } from "sonner";
import { updateNotificationPrefs, type NotificationPrefs } from "@/lib/settings";

export function NotificationPrefsForm({ prefs }: { prefs: NotificationPrefs }) {
  const router = useRouter();
  const [pending, setPending] = useState(false);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    setPending(true);
    try {
      await updateNotificationPrefs({
        weeklyDigest: data.get("weeklyDigest") === "on",
        productUpdates: data.get("productUpdates") === "on",
      });
      toast.success("Preferences saved");
      router.push("/settings");
    } catch {
      toast.error("Could not save preferences");
    } finally {
      setPending(false);
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <label>
        <input type="checkbox" name="weeklyDigest" defaultChecked={prefs.weeklyDigest} /> Weekly digest
      </label>
      <label>
        <input type="checkbox" name="productUpdates" defaultChecked={prefs.productUpdates} /> Product updates
      </label>
      <button type="submit" disabled={pending}>
        Save
      </button>
    </form>
  );
}

