type ResizeMessage = { type: "resize"; height: number };

function toResizeMessage(data: unknown): ResizeMessage | null {
  if (typeof data !== "object" || data === null) return null;
  const record = data as Record<string, unknown>;
  if (record.type !== "resize" || typeof record.height !== "number") return null;
  return { type: "resize", height: record.height };
}

export function listenForResize(frame: HTMLIFrameElement, allowedOrigin: string): () => void {
  const handler = (event: MessageEvent<unknown>) => {
    if (event.origin !== allowedOrigin) return;
    const message = toResizeMessage(event.data);
    if (message) frame.style.height = `${message.height}px`;
  };
  window.addEventListener("message", handler);
  return () => window.removeEventListener("message", handler);
}

