import { useEffect } from "react";

type Shortcut = { key: string; meta?: boolean };

export function useKeyboardShortcut(shortcut: Shortcut, onTrigger: () => void) {
  useEffect(() => {
    const controller = new AbortController();
    document.addEventListener(
      "keydown",
      (event) => {
        if (event.key !== shortcut.key) return;
        if (shortcut.meta && !(event.metaKey || event.ctrlKey)) return;
        event.preventDefault();
        onTrigger();
      },
      { signal: controller.signal },
    );
    return () => controller.abort();
  }, [shortcut.key, shortcut.meta, onTrigger]);
}

