import { verifySignature } from "../lib/signatures";
import { handleDelivery } from "../services/deliveries";

const DeliveryEvent = z.object({
  id: z.string(),
  type: z.enum(["delivery.created", "delivery.completed", "delivery.failed"]),
  data: z.object({ deliveryId: z.string(), orderIds: z.array(z.string()) }),
});

export const webhooks = Router();

webhooks.post("/webhooks/deliveries", async (req, res) => {
  if (!verifySignature(req.rawBody, req.header("x-signature"))) {
    return res.status(401).end();
  }
  const parsed = DeliveryEvent.safeParse(JSON.parse(req.rawBody.toString("utf8")));
  if (!parsed.success) {
    return res.status(400).json({ error: "invalid payload" });
  }

  await Promise.all(parsed.data.data.orderIds.map((orderId) => handleDelivery(parsed.data.type, orderId)));
  res.status(204).end();
});

