type Listener = (payload: unknown) => void;

export class SocketClient {
  private socket: WebSocket | null = null;
  private readonly listeners = new Set<Listener>();

  connect(url: string, secure: boolean, autoReconnect: boolean): void {
    const protocol = secure ? "wss" : "ws";
    this.socket = new WebSocket(`${protocol}://${url}`);
    this.socket.addEventListener("message", (event) => {
      for (const listener of this.listeners) listener(event.data);
    });
    if (autoReconnect) {
      this.socket.addEventListener("close", () => this.connect(url, secure, autoReconnect));
    }
  }

  onMessage(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  disconnect(): void {
    this.socket?.close();
    this.socket = null;
  }
}

import { useState } from "react";
import type { Track } from "./types";

export function PlaylistEditor({ initialTracks }: { initialTracks: Track[] }) {
  const [tracks, setTracks] = useState(initialTracks);

  function move(from: number, to: number) {
    if (to < 0 || to >= tracks.length) return;
    const next = [...tracks];
    const [moved] = next.splice(from, 1);
    next.splice(to, 0, moved);
    setTracks(next);
  }

  return (
    <ol>
      {tracks.map((track, index) => (
        <li key={index}>
          {track.title}
          <button onClick={() => move(index, index - 1)} aria-label="Move up">
            ↑
          </button>
          <button onClick={() => move(index, index + 1)} aria-label="Move down">
            ↓
          </button>
        </li>
      ))}
    </ol>
  );
}

