import { useEffect, useRef, useState } from "react";

const ACTIVITY_EVENTS = ["mousemove", "keydown", "pointerdown"] as const;
const CHECK_INTERVAL_MS = 1000;

export function useIdleTimer(timeoutMs: number): boolean {
  const [isIdle, setIsIdle] = useState(false);
  const lastActivity = useRef(Date.now());

  useEffect(() => {
    const markActive = () => {
      lastActivity.current = Date.now();
      setIsIdle(false);
    };
    for (const eventName of ACTIVITY_EVENTS) {
      window.addEventListener(eventName, markActive);
    }
    const intervalId = setInterval(() => {
      setIsIdle(Date.now() - lastActivity.current > timeoutMs);
    }, CHECK_INTERVAL_MS);

    return () => clearInterval(intervalId);
  }, [timeoutMs]);

  return isIdle;
}

