import { useMemo, useState } from "react";
import type { Product } from "../types";

export function ProductFilter({ products }: { products: Product[] }) {
  const [query, setQuery] = useState("");

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return products.filter((product) => product.title.toLowerCase().includes(q));
  }, [products, query]);

  return (
    <>
      <input value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Filter products" />
      <p>{visible.length} results</p>
      <ul>
        {visible.map((product) => (
          <li key={product.sku}>{product.title}</li>
        ))}
      </ul>
    </>
  );
}

import { useEffect, useState } from "react";

export function LiveClock({ timeZone }: { timeZone: string }) {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    setInterval(() => setNow(new Date()), 1000);
  }, []);

  const label = new Intl.DateTimeFormat(undefined, { timeStyle: "medium", timeZone }).format(now);
  return <time dateTime={now.toISOString()}>{label}</time>;
}
